//! Cargo-driven `telnetd.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is telnetd-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_mainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "mainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "mainCRTStartup"),
        o => panic!("telnetd-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "import:advapi32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "import:advapi32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "import:advapi32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/services/telnetd",
        "base/services/telnetd",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("telnetd-rust")
        .rc("base/services/telnetd/telnetd.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
